-- D-33 Receipt, Storage and Handling: FSQM-035 Receipt, Storage and Handling Program, DRAFT.
--
-- SQF 11.6.1.1-.6 and 11.6.3.1-.2 are Non-Compliant. FSQM-035 is reserved in the remediation workbook.
--
-- Owner's answers, 2026-09-22: one dry storage room (ingredients, packaging, finished product on
-- separate shelving), fully dry; mix of shelving and pallets; oldest used first; allergens on their own
-- labelled shelf; walk-ins hold chilled ingredients and in-process / finished product; no overflow
-- storage; deliveries sometimes staged.
--
-- One document and no new form: receipt is recorded on FRM-301 and storage is checked monthly on
-- FRM-913 (rows 11.6.1 and 11.6.3 already exist), so the workbook's SOP-4xx is not needed.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-035') then
    raise exception 'FSQM-035 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-301', 'FRM-702', 'FRM-913', 'FRM-401', 'FRM-704', 'SOP-2.3.4', 'SOP-401',
                            'FSQM-018', 'FSQM-032', 'FSQM-036') and status = 'active') <> 10 then
    raise exception 'a document D-33 names is missing or not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-035', 'Receipt, Storage and Handling Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.6.1.1, 11.6.1.2, 11.6.1.3, 11.6.1.4, 11.6.1.5, 11.6.1.6, 11.6.3.1, 11.6.3.2', true, $q${"purpose": "This program states how Adventure Bakery receives and stores its ingredients, packaging, in-process and finished product so that they stay safe and fit for use: where each is kept, how it is kept apart, how stock is rotated, and how shelf life is controlled.", "scope": "Everything received and stored on site: dry ingredients, chilled ingredients, packaging, in-process product, rework and finished product, in the dry storage room and the walk-in refrigerator and freezer. Chemicals are covered by FSQM-032 and are not stored with food or packaging.", "definitions": "FEFO: first expired, first out - the stock with the soonest best-by date is used first.\nIn-process product: syrup, batter or baked product not yet packed.\nOverflow storage: any place used to hold stock because the normal storage areas are full.", "responsibility": "Production staff - receive, put away and rotate stock, and use the oldest first.\nSQF Practitioner - owns this program, checks storage monthly on the GMP inspection, and decides on stock that is expired, damaged or out of place.", "procedure": ["Where things are kept", "• Dry storage room: dry ingredients, packaging and finished product, each on its own shelving. The room is dry, with no sink, floor drain or wet cleaning in or next to it (SQF 11.6.3.1).", "• Walk-in refrigerator: chilled ingredients, and in-process or finished product held cold. Walk-in freezer: anything that needs to stay frozen. Both are monitored under SOP-401.", "• Chemicals are kept in the chemical locker under FSQM-032, never in the dry storage room or the walk-ins.", "• No overflow or temporary storage is used. Everything fits in the rooms above (SQF 11.6.1.5, 11.6.1.6). Before any other place is used, the SQF Practitioner assesses the risk in writing and this program is revised to include it.", "Receipt", "• Every delivery is checked and recorded on FRM-301 under SOP-2.3.4: supplier approved, packaging intact, lot and best-by recorded, and the temperature of chilled goods.", "• Chilled goods are received at 41°F or below and go into the walk-in first, before anything else is put away. Frozen goods are received frozen.", "• Dry goods and packaging are put away the same day. Until then they wait in the receiving area, off the floor, away from production and never on the production floor.", "• A delivery that fails its check is held on FRM-702 under FSQM-018 and kept apart from accepted stock.", "Keeping things apart", "• Ingredients, packaging and finished product each have their own shelving in the dry storage room.", "• Allergen ingredients are kept on their own shelf, labelled, and never above non-allergen ingredients (SQF 11.6.1.2, 2.8.1.3).", "• In the walk-in, in-process and finished product is covered and kept on shelves above raw chilled ingredients such as eggs and dairy, never below them (SQF 11.6.1.2).", "• Held or rejected stock is tagged under FSQM-018 and kept apart from stock in use.", "• Clean utensils and spare equipment parts are kept covered and off the floor, never in the chemical locker.", "Shelving and pallets", "• All stock is kept off the floor, on shelving or on clean, dry, undamaged pallets, with a gap from the walls wide enough to clean and inspect behind (SQF 11.6.3.2).", "• Shelving is metal, wire or plastic - smooth and cleanable. Wooden shelving is not used.", "• The dry storage room floor is swept weekly, including under the shelving and pallets, and any spill is cleaned up when it happens.", "Stock rotation", "• Stock is used FEFO: the soonest best-by first. New deliveries are put behind or below older stock of the same item (SQF 11.6.1.3).", "• Rotation is checked monthly on the GMP inspection, FRM-913, row 11.6.1.", "Shelf life", "• Materials: the best-by date is recorded on FRM-301 at receipt, and checked when the material is taken for weighing. Expired material is not used; it is held on FRM-702 (SQF 11.6.1.4).", "• Opened ingredients are closed again after use, or moved into a lidded container labelled with the product name, lot and best-by, so they keep their shelf life and their traceability.", "• In-process product: batter is all baked the day it is mixed. Anything else held for later is covered, labelled with what it is, the lot and the date it was made, and kept in the walk-in. Anything unlabelled is discarded.", "• Rework: the only rework is re-pouching a pouch that fails its seal. Re-pouched product keeps its original lot and best-by (FSQM-018).", "• Finished product: its shelf life is set on FRM-704 and its best-by and lot are printed on every pack. Finished product is dispatched FEFO under FSQM-036."], "form_references": "FRM-301 - Incoming Material Receiving & Inspection Log\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-913 - GMP / Food Safety Inspection Record (monthly storage check)\nFRM-401 - Temperature Monitoring Review (walk-ins)\nFRM-704 - Finished Product Specification (shelf life)", "records": "• FRM-301 receiving records\n• FRM-702 hold records\n• FRM-913 monthly GMP inspections, rows 11.6.1 and 11.6.3\n• FRM-401 monthly temperature reviews", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.6.1.1 to 11.6.1.6 (Receipt, Storage, and Handling of Goods) and 11.6.3.1, 11.6.3.2 (Storage of Dry Ingredients, Packaging, and Shelf Stable Packaged Goods).\n\nSOP-2.3.4 Vendor Approval and FRM-301 - receiving checks.\nSOP-401 Temperature-Controlled Storage - the walk-ins.\nFSQM-018 Non-Conforming Product and Equipment - held stock and rework.\nFSQM-032 Chemical Control Program - chemical storage.\nFSQM-036 Loading, Transport and Unloading Program - dispatch.", "revision_history": "New - 2026-09-22 - DRAFT under D-33, for the eight Non-Compliant findings against 11.6.1 and 11.6.3.\n\nWHAT THE SITE DOES NOW (owner, 2026-09-22): one dry storage room holds ingredients, packaging and finished product on separate shelving; the room is fully dry; stock is on a mix of shelving and pallets; the oldest is used first; allergen ingredients have their own labelled shelf; the walk-ins hold chilled ingredients and in-process or finished product; no overflow storage is used; deliveries are sometimes put straight away and sometimes staged first.\n\nONE DOCUMENT, NO NEW FORM: the workbook allowed for an SOP-4xx as well. Receiving is already recorded on FRM-301 and storage is already checked monthly on FRM-913, so a second document and a new form would record the same things twice.\n\nTO CONFIRM BEFORE ISSUE: that chemicals are never kept in the dry storage room, and the weekly sweep of the dry storage room."}$q$::jsonb);

do $verify$
begin
  if (select jsonb_array_length(content->'procedure') from public.sop_documents where sop_number = 'FSQM-035') <> 29 then
    raise exception 'FSQM-035 procedure not 29 lines.';
  end if;
end $verify$;

commit;
